package com.careerai.backend.dto;

import java.util.List;

/**
 * Interview-preparation context from a resume (and optionally a job description).
 * engine GEMINI: focus topics and question lists were generated by AI from the resume text.
 * engine RULE_BASED: AI was unavailable (aiStatus UNAVAILABLE, aiMessage says why); focus topics
 * come from deterministic skill/section matching and the question lists are empty.
 * No interview is started here.
 */
public record InterviewPreparationResponse(
    Long resumeId,
    String resumeTitle,
    String interviewType,
    String targetRole,
    String engine,
    String note,
    String aiStatus,
    String aiMessage,
    List<String> resumeSkills,
    List<String> resumeSections,
    List<String> jobSkills,
    List<String> jobKeywords,
    List<String> matchedSkills,
    List<String> missingSkills,
    List<FocusTopic> focusTopics,
    List<String> likelyResumeQuestions,
    List<String> projectQuestions,
    List<String> experienceQuestions,
    List<String> skillQuestions,
    List<String> potentialWeakAreas
) {

    /** priority: CORE (in resume and job/resume), GAP (job asks, resume lacks), GENERAL. */
    public record FocusTopic(String name, String priority, String reason, String practiceRoute) {
    }
}
